/**
 * a11y-patches.js
 * Runtime accessibility patches for pytorch_sphinx_theme2.
 *
 * Fixes violations that cannot be addressed in Jinja templates alone because
 * they are generated by pydata-sphinx-theme internals or injected by third-party
 * scripts (e.g. the version switcher).
 *
 * WCAG criteria addressed:
 *   - 4.1.2  Name, Role, Value  → summary-name, select-name
 *   - 1.3.1  Info & Relationships → definition-list (dl/dt/dd structure)
 *   - 2.1.1  Keyboard           → scrollable-region-focusable
 *   - 1.4.1  Use of Colour      → inline link cookie-banner underline fallback
 *
 * Note: search-toggle aria-label (WCAG 1.3.1, 4.1.2) is handled directly in
 * search-field-custom.html — no JS required.
 */

(function () {
  "use strict";

  // ── Helpers ──────────────────────────────────────────────────────────────

  /** Run fn after the DOM is ready (works whether DOMContentLoaded has already fired). */
  function onReady(fn) {
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", fn);
    } else {
      fn();
    }
  }

  /** Create a visually-hidden text node for screen readers. */
  function srOnly(text) {
    var span = document.createElement("span");
    span.className = "visually-hidden";
    span.textContent = text;
    return span;
  }

  // ── Fix 1: summary-name (WCAG 4.1.2) ────────────────────────────────────
  // pydata-sphinx-theme generates <summary> elements that contain only a
  // <span role="presentation"> chevron icon (case 2 in toctree.py).
  // Screen readers announce these as "collapsed" with no label.
  // Fix: look up the sibling <a> link and inject its text as a visually-hidden
  // label inside the <summary>.

  function fixSummaryNames() {
    var summaries = document.querySelectorAll(
      ".bd-sidebar-primary summary, .bd-sidebar-secondary summary, nav.bd-links summary"
    );

    summaries.forEach(function (summary) {
      // Skip if already labelled
      if (
        summary.getAttribute("aria-label") ||
        summary.getAttribute("aria-labelledby")
      ) {
        return;
      }

      // Check if the only child is a presentational span (case 2)
      var children = Array.from(summary.children);
      var hasOnlyPresentationalContent =
        children.length > 0 &&
        children.every(function (el) {
          return el.getAttribute("role") === "presentation";
        });

      if (!hasOnlyPresentationalContent) {
        return; // case 1: heading text is already inside summary — no fix needed
      }

      // Find the sibling link in the parent <li>
      var li = summary.closest("li");
      if (!li) return;
      var link = li.querySelector(":scope > a.reference, :scope > a.nav-link");
      if (!link) return;

      var linkText = link.textContent.trim();
      if (!linkText) return;

      // Determine expand/collapse state label
      var details = summary.closest("details");
      var isOpen = details && details.hasAttribute("open");
      var actionLabel = isOpen ? "Collapse" : "Expand";

      summary.setAttribute(
        "aria-label",
        actionLabel + " " + linkText + " section"
      );

      // Keep the label in sync when the details element is toggled
      if (details) {
        details.addEventListener("toggle", function () {
          var nowOpen = details.hasAttribute("open");
          summary.setAttribute(
            "aria-label",
            (nowOpen ? "Collapse" : "Expand") + " " + linkText + " section"
          );
        });
      }
    });
  }

  // ── Fix 2: select-name (WCAG 4.1.2) ─────────────────────────────────────
  // The pydata-sphinx-theme version switcher renders a <select> element with
  // no associated <label> or aria-label.

  function fixSelectNames() {
    // Version switcher select (pydata-sphinx-theme)
    document
      .querySelectorAll(".version-switcher__menu select, select.version-switcher__button")
      .forEach(function (sel) {
        if (!sel.getAttribute("aria-label") && !sel.getAttribute("aria-labelledby")) {
          sel.setAttribute("aria-label", "Select documentation version");
        }
      });

    // Any remaining unlabelled <select> elements
    document.querySelectorAll("select").forEach(function (sel) {
      if (
        !sel.getAttribute("aria-label") &&
        !sel.getAttribute("aria-labelledby") &&
        !sel.id
      ) {
        // Try to infer a label from surrounding text
        var parent = sel.parentElement;
        var label = parent ? parent.textContent.trim().split("\n")[0].trim() : "";
        sel.setAttribute(
          "aria-label",
          label || "Select an option"
        );
      }
    });
  }

  // ── Fix 3: scrollable-region-focusable (WCAG 2.1.1) ─────────────────────
  // Wide API tables and code blocks that overflow their container are
  // scrollable but not keyboard-reachable. Add tabindex="0" and a
  // descriptive aria-label so keyboard users can scroll them.

  function fixScrollableRegions() {
    // Code blocks
    document.querySelectorAll("div.highlight, pre").forEach(function (el) {
      if (el.scrollWidth > el.clientWidth || el.scrollHeight > el.clientHeight) {
        if (!el.hasAttribute("tabindex")) {
          el.setAttribute("tabindex", "0");
          el.setAttribute("role", "region");
          if (!el.getAttribute("aria-label")) {
            el.setAttribute("aria-label", "Scrollable code block");
          }
        }
      }
    });

    // Wide tables
    document
      .querySelectorAll(".bd-content table, .bd-article-container table")
      .forEach(function (table) {
        var wrapper = table.parentElement;
        if (!wrapper) return;
        if (
          wrapper.scrollWidth > wrapper.clientWidth &&
          !wrapper.hasAttribute("tabindex")
        ) {
          wrapper.setAttribute("tabindex", "0");
          wrapper.setAttribute("role", "region");
          if (!wrapper.getAttribute("aria-label")) {
            // Use the table caption or a generic label
            var caption = table.querySelector("caption");
            wrapper.setAttribute(
              "aria-label",
              caption ? caption.textContent.trim() : "Scrollable table"
            );
          }
        }
      });
  }

  // ── Fix 4: definition-list (WCAG 1.3.1) ─────────────────────────────────
  // Sphinx-generated API docs sometimes wrap <dt>/<dd> pairs inside <div>
  // children of a <dl>, which is invalid HTML and confuses screen readers.
  // Unwrap the divs so the <dl> contains only <dt>/<dd> directly.

  function fixDefinitionLists() {
    document
      .querySelectorAll("dl > div:not([class*='highlight'])")
      .forEach(function (div) {
        var dl = div.parentElement;
        if (!dl || dl.tagName !== "DL") return;
        // Move all children of the div up into the dl, then remove the div
        while (div.firstChild) {
          dl.insertBefore(div.firstChild, div);
        }
        dl.removeChild(div);
      });
  }

  // ── Fix 5: version switcher select (WCAG 4.1.2) ──────────────────────────
  // The version switcher button dropdown is sometimes rendered as a <select>
  // injected after page load. Use a MutationObserver to catch late injection.

  function observeVersionSwitcher() {
    var observer = new MutationObserver(function (mutations) {
      mutations.forEach(function (mutation) {
        mutation.addedNodes.forEach(function (node) {
          if (node.nodeType !== 1) return;
          var selects = node.querySelectorAll
            ? node.querySelectorAll("select")
            : [];
          selects.forEach(function (sel) {
            if (
              !sel.getAttribute("aria-label") &&
              !sel.getAttribute("aria-labelledby")
            ) {
              sel.setAttribute("aria-label", "Select documentation version");
            }
          });
          if (node.tagName === "SELECT" && !node.getAttribute("aria-label")) {
            node.setAttribute("aria-label", "Select documentation version");
          }
        });
      });
    });

    observer.observe(document.body, { childList: true, subtree: true });
  }

  // ── Fix 6: link-in-text-block — cookie banner links (WCAG 1.4.1) ─────────
  // The HubSpot cookie banner injects links that are distinguishable from
  // surrounding text only by colour. The SCSS fix in _a11y.scss covers
  // static prose links; this function handles the dynamically-injected
  // cookie banner links that are not present at DOMContentLoaded.
  // Fix: ensure cookie-banner links always have a visible underline.

  function fixCookieBannerLinks() {
    var selectors = [
      "#hs-eu-policy-wording a",
      "#hs-eu-cookie-disclaimer a",
      ".hs-cookie-notification-position-bottom a",
    ];
    document.querySelectorAll(selectors.join(", ")).forEach(function (link) {
      if (!link.style.textDecoration) {
        link.style.textDecoration = "underline";
        link.style.textUnderlineOffset = "0.15em";
      }
    });
  }

  // ── Initialise ───────────────────────────────────────────────────────────

  onReady(function () {
    fixSummaryNames();
    fixSelectNames();
    fixScrollableRegions();
    fixDefinitionLists();
    observeVersionSwitcher();
    fixCookieBannerLinks();
  });
})();
